# Test 4: the branch skip pattern has ONE source (#1460)
#
# #1458 mirrored the skip alternation into the pre-push hook and
# version-check.yml and this test held the two copies equal, which made drift
# loud but not impossible. The pattern now lives in
# scripts/ci/version-skip-pattern.sh and both consumers source it. This test
# is the inversion: the file defines the pattern with the expected behaviour,
# each consumer SOURCES it, and neither carries an inline alternation any more.
# The emptied-file and missing-file failure modes are proved by
# tests/ci/fault-arms/version-skip-pattern.sh, not here.
test_skip_regex_parity() {
    log_section "Test 4: Branch skip pattern has one source (#1460)"

    local pattern_file="${PROJECT_ROOT}/scripts/ci/version-skip-pattern.sh"
    local hook_file="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local ci_file="${PROJECT_ROOT}/.github/workflows/version-check.yml"

    # 4a: the file defines a non-empty pattern, read the way a consumer reads it.
    local pattern
    pattern=$(/bin/bash -c '. "$1" && printf "%s" "${VERSION_SKIP_PATTERN:-}"' _ "$pattern_file" 2>&1)
    if [[ -z "$pattern" ]]; then
        log_fail "scripts/ci/version-skip-pattern.sh does not define VERSION_SKIP_PATTERN"
        return
    fi
    log_pass "scripts/ci/version-skip-pattern.sh defines VERSION_SKIP_PATTERN"

    # 4b: behaviour, not text. Every conventional-commit prefix, a release-please
    # branch and a Dependabot branch skip; a bare-named branch and main do not.
    local wrong=()
    local skip_names=(docs/x chore/x ci/x style/x test/x feat/x fix/x perf/x refactor/x issue/x bug/x
        release-please--branches--main dependabot/npm_and_yarn/lodash-4.17.21)
    local enforce_names=(main hotfix-1457 docs bugfix/x feature/x)
    local name
    for name in "${skip_names[@]}"; do
        [[ "$name" =~ $pattern ]] || wrong+=("should-skip:$name")
    done
    for name in "${enforce_names[@]}"; do
        [[ "$name" =~ $pattern ]] && wrong+=("should-enforce:$name")
    done
    if [[ ${#wrong[@]} -eq 0 ]]; then
        log_pass "pattern skips ${#skip_names[@]} owned branch shapes and enforces ${#enforce_names[@]} bare ones"
    else
        log_fail "pattern misclassifies: ${wrong[*]}"
    fi

    # 4c: each consumer sources the shared file on a non-comment line.
    local consumer
    for consumer in "$hook_file" "$ci_file"; do
        # No -q here: under pipefail, grep -q exits on the first match and the
        # producer grep dies with SIGPIPE (141), which flips this if to the else
        # branch precisely when the file DOES source the script (#3974, same
        # class as #603). Reading all input keeps the pipeline status honest.
        if grep -v '^[[:space:]]*#' "$consumer" | grep -E '(source|[[:space:]]\.)[[:space:]]+"?[^"[:space:]]*scripts/ci/version-skip-pattern\.sh' >/dev/null; then
            log_pass "$(basename "$consumer") sources scripts/ci/version-skip-pattern.sh"
        else
            log_fail "$(basename "$consumer") does not source scripts/ci/version-skip-pattern.sh"
        fi
    done

    # 4d: no consumer carries an inline alternation (the exact shape the old
    # parity test extracted; its presence now means a second copy came back).
    local inline
    for consumer in "$hook_file" "$ci_file"; do
        inline=$(grep -nE '\^\([a-z|]+\)/' "$consumer" || true)
        if [[ -z "$inline" ]]; then
            log_pass "$(basename "$consumer") carries no inline skip alternation"
        else
            log_fail "$(basename "$consumer") has an inline skip alternation again -> ${inline}"
        fi
    done
}

# Test 5: the hook parses and runs under the bash the shebang actually gets
#
# bin/git-hooks/pre-push declares `#!/bin/bash`. On macOS that is the bundled
# bash 3.2.57, NOT whatever bash 4/5 is on PATH from brew. A bash-4-only
# builtin therefore fails only on the machine the hook actually runs on, and
# Tests 1-4 all passed with `mapfile` live in the discovery block because none
# of them execute or parse the file under /bin/bash.
#
# Every branch below reports the REAL error text rather than discarding it —
# a regression test that hides why it failed just moves the debugging cost.
test_bash32_compatibility() {
    echo ""
    echo "Test 5: pre-push is compatible with /bin/bash (macOS bash 3.2)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"

    # 5a: no bash-4-only builtins outside comments. awk (not grep|grep) so a
    # zero-match result is exit 0 and a real scan failure stays distinguishable.
    local offenders
    offenders=$(awk '
        /^[[:space:]]*#/ { next }
        /(^|[^#[:alnum:]_])(mapfile|readarray)[[:space:]]/ { print NR ": " $0 }
    ' "$hook")
    if [[ -z "$offenders" ]]; then
        log_pass "no mapfile/readarray invocation (bash 4+ builtins)"
    else
        log_fail "bash 4+ builtin in a #!/bin/bash script -> ${offenders}"
    fi

    # 5b: /bin/bash itself must be able to PARSE the hook. Keep the parse error.
    # (see test_resolve_push_branch below for the #3290 refspec regression)
    local parse_err
    if parse_err=$(/bin/bash -n "$hook" 2>&1); then
        log_pass "/bin/bash -n parses the hook"
    else
        log_fail "/bin/bash -n rejected the hook -> ${parse_err}"
    fi

    # 5c: discovery must actually find tests under /bin/bash. This is the
    # assertion that fails loudly on the real bug: with mapfile the array came
    # back empty and the hook exited 1 claiming no tests exist.
    local discover_out
    if discover_out=$(/bin/bash -c '
        cd "$1" || exit 1
        SKIP_UNIT_TESTS=()
        CI_UNIT_TESTS=()
        while IFS= read -r file; do
            [[ -n "$file" ]] || continue
            CI_UNIT_TESTS+=("$file")
        done < <(find tests/unit \( -name "test-*.sh" -o -name "test-*.mjs" \) -type f | sort)
        echo "${#CI_UNIT_TESTS[@]}"
    ' _ "$PROJECT_ROOT" 2>&1); then
        if [[ "$discover_out" =~ ^[0-9]+$ ]] && (( discover_out > 0 )); then
            log_pass "discovery yields ${discover_out} unit tests under /bin/bash"
        else
            log_fail "discovery returned no usable count -> ${discover_out}"
        fi
    else
        log_fail "discovery errored under /bin/bash -> ${discover_out}"
    fi
}

# Test 6: the branch is resolved from the PUSHED refspec, not from HEAD (#3290)
#
# `git rev-parse --abbrev-ref HEAD` returns the literal string "HEAD" in a
# detached worktree, so the conventional-commit prefix exemption never matched
# and the version gate fired on branches that are exempt. Pushing a branch that
# another worktree holds REQUIRES detached HEAD (git refuses one branch in two
# worktrees), so the hook penalised the only safe way to do it.
#
# Sources just resolve_push_branch, the same isolation trick Test 1 uses for
# run_with_timeout, so this never executes the real suite.
test_resolve_push_branch() {
    echo ""
    echo "Test 6: branch resolves from the pushed refspec (#3290)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local fn
    fn=$(sed -n '/^resolve_push_branch()/,/^}/p' "$hook")

    if [[ -z "$fn" ]]; then
        log_fail "resolve_push_branch() not found in the hook — the #3290 fix is gone"
        return
    fi
    log_pass "resolve_push_branch() is present"

    # A real refspec line, exactly what git writes on stdin.
    local got
    got=$(bash -c "$fn"$'\n''resolve_push_branch' <<<'refs/heads/x 1111111 refs/heads/fix/my-branch 2222222')
    if [[ "$got" == "fix/my-branch" ]]; then
        log_pass "refspec on stdin resolves to fix/my-branch"
    else
        log_fail "refspec resolved to '${got}', expected fix/my-branch"
    fi

    # The regression itself: detached HEAD + HEAD:<branch>. The local ref is a
    # SHA (not a branch), which is what made the old code produce "HEAD".
    got=$(bash -c "$fn"$'\n''resolve_push_branch' <<<'3333333 3333333 refs/heads/fix/detached-push 4444444')
    if [[ "$got" == "fix/detached-push" ]]; then
        log_pass "detached-HEAD push resolves to fix/detached-push, not HEAD"
    else
        log_fail "detached push resolved to '${got}', expected fix/detached-push"
    fi

    # A tag-only push must NOT be mistaken for a branch.
    got=$(bash -c "$fn"$'\n''resolve_push_branch' <<<'refs/tags/v1 5555555 refs/tags/v1 6666666')
    if [[ "$got" != "v1" ]]; then
        log_pass "tag refspec does not resolve to a branch name (got '${got}')"
    else
        log_fail "tag refspec was treated as a branch"
    fi

    # Empty stdin must fall back to HEAD so a manual run behaves as before.
    got=$(cd "$PROJECT_ROOT" && bash -c "$fn"$'\n''resolve_push_branch' </dev/null)
    local head_branch
    head_branch=$(cd "$PROJECT_ROOT" && git rev-parse --abbrev-ref HEAD)
    if [[ "$got" == "$head_branch" ]]; then
        log_pass "empty stdin falls back to HEAD (${got})"
    else
        log_fail "empty-stdin fallback gave '${got}', expected '${head_branch}'"
    fi
}

# Test 7: the tail guard rejects repository-local config drift (#4070)
test_rejects_repo_config_drift() {
    echo ""
    echo "Test 7: pre-push rejects repository-local config drift (#4070)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local snapshot_fn guard_fn tmp normal rc=0 tail
    snapshot_fn=$(sed -n '/^capture_initial_repo_config()/,/^}/p' "$hook")
    guard_fn=$(sed -n '/^assert_repo_config_unchanged()/,/^}/p' "$hook")
    if [[ -z "$snapshot_fn" || -z "$guard_fn" ]]; then
        log_fail "repository-config snapshot or guard is missing"
        return
    fi

    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-pre-push-bare.XXXXXX")
    normal="$tmp/normal"
    git init -q "$normal"
    git -C "$normal" config user.email initial@example.test

    rc=0
    ( cd "$normal" && bash -c "$snapshot_fn"$'\n'"$guard_fn"$'\n''capture_initial_repo_config; assert_repo_config_unchanged' ) || rc=$?
    if [[ $rc -eq 0 ]]; then
        log_pass "tail guard allows unchanged disposable repository config"
    else
        log_fail "tail guard rejected unchanged disposable repository config (rc=$rc)"
    fi

    rc=0
    ( cd "$normal" && bash -c "$snapshot_fn"$'\n'"$guard_fn"$'\n''capture_initial_repo_config; git config core.bare true; assert_repo_config_unchanged' ) >/dev/null 2>&1 || rc=$?
    if [[ $rc -ne 0 ]]; then
        log_pass "tail guard rejects a disposable repository after core.bare flips"
    else
        log_fail "tail guard allowed a disposable repository after core.bare flipped"
    fi
    git -C "$normal" config core.bare false

    rc=0
    ( cd "$normal" && bash -c "$snapshot_fn"$'\n'"$guard_fn"$'\n''capture_initial_repo_config; git config user.email changed@example.test; assert_repo_config_unchanged' ) >/dev/null 2>&1 || rc=$?
    if [[ $rc -ne 0 ]]; then
        log_pass "tail guard rejects a changed repo-local user.email"
    else
        log_fail "tail guard allowed a changed repo-local user.email"
    fi
    git -C "$normal" config user.email initial@example.test

    rc=0
    ( cd "$normal" && bash -c "$snapshot_fn"$'\n'"$guard_fn"$'\n''capture_initial_repo_config; git config --unset user.email; assert_repo_config_unchanged' ) >/dev/null 2>&1 || rc=$?
    if [[ $rc -ne 0 ]]; then
        log_pass "tail guard distinguishes an unset user.email from its initial value"
    else
        log_fail "tail guard allowed repo-local user.email to become unset"
    fi

    rc=0
    ( cd "$normal" && bash -c "$snapshot_fn"$'\n'"$guard_fn"$'\n''capture_initial_repo_config; git config user.email changed@example.test; assert_repo_config_unchanged' ) >/dev/null 2>&1 || rc=$?
    if [[ $rc -ne 0 ]]; then
        log_pass "tail guard distinguishes a set user.email from initially unset"
    else
        log_fail "tail guard allowed an initially unset user.email to become set"
    fi

    tail=$(tail -n 16 "$hook")
    if [[ "$tail" == *'assert_repo_config_unchanged'* && "$tail" == *'Pre-push validation passed'* ]]; then
        log_pass "repository-config guard remains wired at the hook tail"
    else
        log_fail "repository-config guard is not wired at the hook tail"
    fi
    rm -rf "$tmp"
}

# Test 8: the payload probe clears the inherited Git repository context.
test_probe_fixture_git_environment_scrub() {
    echo ""
    echo "Test 8: payload probe fixture git init clears inherited repository context (#4070)"

    local files=(
        "tests/ci/restricted-smoke/probe-payload-rules.sh"
    )
    local child_script='
for name in GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_PREFIX GIT_COMMON_DIR GIT_OBJECT_DIRECTORY; do
    if declare -p "$name" >/dev/null 2>&1; then
        echo "still set: $name" >&2
        exit 1
    fi
done
git init -q --bare "$1"
'
    local tmp caller file fixture stanza output caller_bare i=0

    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-fixture-git-env.XXXXXX")
    caller="$tmp/caller"
    git init -q "$caller"

    for file in "${files[@]}"; do
        # Stop at the command boundary even if a variable is removed. A range
        # ending at a variable name could accidentally include an eval script.
        stanza=$(awk '
            /^unset GIT_DIR / {
                print
                while ($0 ~ /\\$/) {
                    if (getline <= 0) exit
                    print
                }
                exit
            }
        ' "$PROJECT_ROOT/$file")
        if [[ -z "$stanza" ]]; then
            log_fail "$file has no executable Git-environment scrub stanza"
            continue
        fi

        fixture="$tmp/fixture-$i.git"
        i=$((i + 1))
        if output=$(env \
            GIT_DIR="$caller/.git" \
            GIT_WORK_TREE="$caller" \
            GIT_INDEX_FILE="$caller/.git/index" \
            GIT_PREFIX="$caller" \
            GIT_COMMON_DIR="$caller/.git" \
            GIT_OBJECT_DIRECTORY="$caller/.git/objects" \
            /bin/bash -c "$stanza"$'\n'"$child_script" _ "$fixture" 2>&1); then
            :
        else
            log_fail "$file did not clear every injected Git variable -> $output"
            continue
        fi

        caller_bare=$(git -C "$caller" config --bool core.bare 2>/dev/null || true)
        if [[ -d "$fixture" && -f "$fixture/HEAD" && "$caller_bare" == "false" ]]; then
            log_pass "$file isolates bare fixture init from the disposable caller"
        else
            log_fail "$file fixture/caller state is wrong (fixture=$fixture core.bare=${caller_bare:-unset})"
        fi
    done
    rm -rf "$tmp"
}

# Test 9: hook Vitest must not inherit this hook's repository locators.
test_vitest_git_environment_scrub() {
    echo ""
    echo "Test 9: hook Vitest clears inherited repository context (#4070)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local wrapper command tmp caller fake_bin result hook_log output
    wrapper=$(awk '
        /if ! \(cd src\/hooks && env -u GIT_DIR/ {
            print
            while ($0 ~ /\\$/) {
                if (getline <= 0) exit
                print
            }
            exit
        }
    ' "$hook")
    if [[ -z "$wrapper" ]]; then
        log_fail "could not extract the hook Vitest wrapper"
        return
    fi
    command="${wrapper#*&& }"
    command="${command%); then}"

    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-vitest-git-env.XXXXXX")
    caller="$tmp/caller"
    fake_bin="$tmp/bin"
    result="$tmp/fake-npx-result"
    hook_log="$tmp/hook.log"
    mkdir -p "$fake_bin"
    git init -q "$caller"
    printf '%s\n' \
        '#!/bin/bash' \
        'for name in GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_PREFIX GIT_COMMON_DIR GIT_OBJECT_DIRECTORY; do' \
        '  if printenv "$name" >/dev/null; then echo "still set: $name" >"$FAKE_NPX_RESULT"; exit 1; fi' \
        'done' \
        'if [[ "$*" != "vitest run --reporter=dot --maxWorkers=$MAX_JOBS" ]]; then echo "args: $*" >"$FAKE_NPX_RESULT"; exit 1; fi' \
        'echo ok >"$FAKE_NPX_RESULT"' > "$fake_bin/npx"
    chmod +x "$fake_bin/npx"

    if output=$(cd "$PROJECT_ROOT/src/hooks" && env \
        PATH="$fake_bin:$PATH" \
        FAKE_NPX_RESULT="$result" \
        HOOK_LOG="$hook_log" \
        MAX_JOBS=4 \
        GIT_DIR="$caller/.git" \
        GIT_WORK_TREE="$caller" \
        GIT_INDEX_FILE="$caller/.git/index" \
        GIT_PREFIX="$caller" \
        GIT_COMMON_DIR="$caller/.git" \
        GIT_OBJECT_DIRECTORY="$caller/.git/objects" \
        /bin/bash -c "$command" 2>&1); then
        :
    else
        log_fail "hook Vitest wrapper did not isolate fake npx -> $output"
        rm -rf "$tmp"
        return
    fi

    if [[ "$(<"$result")" == "ok" ]]; then
        log_pass "hook Vitest invokes fake npx with all repository locators unset"
    else
        log_fail "hook Vitest wrapper result: $(<"$result")"
    fi
    rm -rf "$tmp"
}

# Test 10: no pre-push stage inherits a linked worktree's GIT_DIR (#4070).
#
# git exports GIT_DIR=<main>/.git/worktrees/<name> (and no GIT_WORK_TREE) to a
# hook run from a linked worktree. A plain `git init` in a temp dir under that
# env re-initialises the MAIN repository and writes core.bare=true into its
# config. Test 9 covers the Vitest stage only; this covers every stage, by
# asserting the hook drops the locators once, before the first stage runs.
test_stages_do_not_inherit_worktree_git_dir() {
    echo ""
    echo "Test 10: no pre-push stage inherits a linked worktree's GIT_DIR (#4070)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local drop_fn tmp main wt hook_git_dir fixture_body bare top rc call_line stage_line
    drop_fn=$(sed -n '/^drop_inherited_git_locators()/,/^}/p' "$hook")

    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-pre-push-wt-env.XXXXXX")
    tmp=$(cd "$tmp" && pwd -P)
    main="$tmp/main"
    wt="$main/.worktrees/wt"
    git init -q "$main"
    git -C "$main" -c user.email=t@t -c user.name=t -c commit.gpgsign=false \
        commit -q --allow-empty -m init
    git -C "$main" worktree add -q "$wt" -b wt
    hook_git_dir="$main/.git/worktrees/wt"
    # What a pre-push stage fixture does: git init in a fresh temp dir.
    fixture_body='f=$(mktemp -d "$FIXTURE_ROOT/fixture.XXXXXX") && (cd "$f" && git init -q)'

    # Reads main's core.bare straight from its config file; "unset" if absent.
    main_bare() {
        local v
        if v=$(git config --file "$main/.git/config" --get core.bare); then
            printf '%s' "$v"
        else
            printf 'unset'
        fi
    }

    # Control: without the scrub, the fixture must flip the main repo. If it
    # does not, this test no longer reproduces #4070 and proves nothing.
    rc=0
    ( cd "$wt" && env GIT_DIR="$hook_git_dir" FIXTURE_ROOT="$tmp" \
        /bin/bash -c "$fixture_body" ) >/dev/null 2>&1 || rc=$?
    bare=$(main_bare)
    if [[ "$bare" == "true" ]]; then
        log_pass "control: git init under a worktree hook env flips main core.bare"
    else
        log_fail "control no longer reproduces #4070 (core.bare=$bare rc=$rc); test is vacuous"
    fi
    git config --file "$main/.git/config" core.bare false

    if [[ -z "$drop_fn" ]]; then
        log_fail "pre-push defines no drop_inherited_git_locators()"
        rm -rf "$tmp"
        return
    fi

    rc=0
    ( cd "$wt" && env GIT_DIR="$hook_git_dir" FIXTURE_ROOT="$tmp" \
        /bin/bash -c "$drop_fn"$'\n''drop_inherited_git_locators'$'\n'"$fixture_body" ) >/dev/null 2>&1 || rc=$?
    bare=$(main_bare)
    if [[ "$bare" == "false" && $rc -eq 0 ]]; then
        log_pass "after the scrub, a stage fixture's git init leaves main core.bare=false"
    else
        log_fail "after the scrub, main core.bare=$bare (rc=$rc)"
    fi

    rc=0
    top=$(cd "$wt" && env GIT_DIR="$hook_git_dir" /bin/bash -c \
        "$drop_fn"$'\n''drop_inherited_git_locators; if printenv GIT_DIR >/dev/null; then echo still-set; fi; git rev-parse --show-toplevel' 2>&1) || rc=$?
    if [[ "$top" == "$wt" && $rc -eq 0 ]]; then
        log_pass "after the scrub, GIT_DIR is gone and git still resolves the worktree"
    else
        log_fail "after the scrub (rc=$rc): $top"
    fi

    # Wiring: called right after cd, before the first validation stage.
    # awk, not grep: a no-match grep under pipefail aborts this whole file.
    call_line=$(awk '/^drop_inherited_git_locators$/ { print NR; exit }' "$hook")
    stage_line=$(awk '/Running TypeScript type check/ { print NR; exit }' "$hook")
    if [[ -n "$call_line" && -n "$stage_line" && "$call_line" -lt "$stage_line" ]]; then
        log_pass "scrub is called before the first validation stage"
    else
        log_fail "scrub call not wired before the first stage (call=${call_line:-none} stage=${stage_line:-none})"
    fi
    rm -rf "$tmp"
}

# Test 11: the scrub keeps GIT_DIR when PROJECT_ROOT does not rediscover the
# same repository (#4070).
#
# The safety branch of drop_inherited_git_locators(): a `git --git-dir=<x> push`
# run from a directory with no .git entry, or from inside some OTHER
# repository, must keep the exported locators, else the rest of the hook runs
# against the wrong repository (or none). Test 10 only exercises the happy
# path, so a mutant that unsets unconditionally survives it; this pins the
# branch by asserting the WARNING is printed and GIT_DIR survives the call.
test_scrub_keeps_locators_without_rediscovery() {
    echo ""
    echo "Test 11: scrub keeps GIT_DIR when the cwd does not rediscover the same repository (#4070)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local drop_fn tmp main other nogit probe out rc
    drop_fn=$(sed -n '/^drop_inherited_git_locators()/,/^}/p' "$hook")
    if [[ -z "$drop_fn" ]]; then
        log_fail "pre-push defines no drop_inherited_git_locators()"
        return
    fi

    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-pre-push-keep-env.XXXXXX")
    tmp=$(cd "$tmp" && pwd -P)
    main="$tmp/main"
    other="$tmp/other"
    nogit="$tmp/nogit"
    git init -q "$main"
    git init -q "$other"
    mkdir -p "$nogit"
    # After the scrub: report whether GIT_DIR survived and which repo git sees.
    probe='drop_inherited_git_locators; if printenv GIT_DIR >/dev/null; then echo "GIT_DIR=$GIT_DIR"; else echo "GIT_DIR=unset"; fi; git rev-parse --absolute-git-dir'

    # Case A: no .git entry anywhere under the cwd. GIT_CEILING_DIRECTORIES
    # stops rediscovery at $tmp so the result does not depend on where TMPDIR
    # lives (the hook's env -u list does not touch it).
    rc=0
    out=$(cd "$nogit" && env GIT_DIR="$main/.git" GIT_CEILING_DIRECTORIES="$tmp" \
        /bin/bash -c "$drop_fn"$'\n'"$probe" 2>&1) || rc=$?
    if [[ $rc -eq 0 && "$out" == *"WARNING: $nogit does not rediscover"*"keeping GIT_DIR"* ]]; then
        log_pass "no .git entry: scrub prints the WARNING"
    else
        log_fail "no .git entry: expected a keeping-GIT_DIR WARNING (rc=$rc): $out"
    fi
    if [[ "$out" == *"GIT_DIR=$main/.git"* && "$out" == *"$main/.git" ]]; then
        log_pass "no .git entry: GIT_DIR is still exported and git still resolves main"
    else
        log_fail "no .git entry: GIT_DIR was dropped or git lost main: $out"
    fi

    # Case B: the cwd is inside a DIFFERENT repository than GIT_DIR names.
    rc=0
    out=$(cd "$other" && env GIT_DIR="$main/.git" \
        /bin/bash -c "$drop_fn"$'\n'"$probe" 2>&1) || rc=$?
    if [[ $rc -eq 0 && "$out" == *"WARNING: $other rediscovers"*"keeping GIT_DIR"* ]]; then
        log_pass "other repository: scrub prints the WARNING"
    else
        log_fail "other repository: expected a keeping-GIT_DIR WARNING (rc=$rc): $out"
    fi
    if [[ "$out" == *"GIT_DIR=$main/.git"* && "$out" == *"$main/.git" ]]; then
        log_pass "other repository: GIT_DIR is still exported and git still resolves main"
    else
        log_fail "other repository: GIT_DIR was dropped or git lost main: $out"
    fi
    rm -rf "$tmp"
}

# Main
# Test 10: the unit-stage job count is env-overridable and load-aware (#4085)
#
# MAX_JOBS used to be a bare 8, lowered only to hw.ncpu. Measured 2026-09-13 at
# 5-minute load 37: eight hook-spawning suites at once on a machine already
# three times oversubscribed, and files that pass standalone in 11 s took 213 s
# and blew their own per-hook budgets. resolve_pre_push_jobs takes ncpu and
# load1 as ARGUMENTS so this test can feed it an absurd load without the real
# machine's state leaking in. Runs under /bin/bash (3.2), the interpreter the
# hook's shebang actually gets.
test_resolve_pre_push_jobs() {
    log_section "Test 10: resolve_pre_push_jobs honours ORK_PRE_PUSH_JOBS and backs off under load (#4085)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local fn
    fn=$(sed -n '/^resolve_pre_push_jobs()/,/^}/p' "$hook")
    if [[ -z "$fn" ]]; then
        log_fail "resolve_pre_push_jobs() not found in the hook"
        return
    fi

    # jobs_case <label> <expected> <ncpu> <load1> [ORK_PRE_PUSH_JOBS]
    jobs_case() {
        local label="$1" want="$2" ncpu="$3" load1="$4" override="${5-}"
        local got
        if [[ -n "$override" ]]; then
            got=$(ORK_PRE_PUSH_JOBS="$override" /bin/bash -c "$fn"'; resolve_pre_push_jobs "$1" "$2"' _ "$ncpu" "$load1" 2>/dev/null)
        else
            got=$(env -u ORK_PRE_PUSH_JOBS /bin/bash -c "$fn"'; resolve_pre_push_jobs "$1" "$2"' _ "$ncpu" "$load1" 2>/dev/null)
        fi
        if [[ "$got" == "$want" ]]; then
            log_pass "$label -> $got"
        else
            log_fail "$label -> got [$got], want [$want]"
        fi
    }

    jobs_case "ORK_PRE_PUSH_JOBS=1 wins over an idle 8-core box"        1 8 0    1
    jobs_case "ORK_PRE_PUSH_JOBS=2 wins over an absurd load"            2 8 999  2
    jobs_case "absurd load (999) on 8 cores floors at 1"                1 8 999
    jobs_case "idle 8 cores gives 8"                                    8 8 0
    jobs_case "idle 16 cores is capped at 8"                            8 16 0
    jobs_case "idle 4 cores gives 4 (never above ncpu)"                 4 4 0
    jobs_case "8 cores at load 5.4 rounds down to 3"                    3 8 5.4
    jobs_case "8 cores at load 5.5 rounds up to 2"                      2 8 5.5
    jobs_case "unreadable load leaves the cap alone"                    8 8 ""
    jobs_case "non-numeric ORK_PRE_PUSH_JOBS is ignored, not honoured"  8 8 0    abc
    jobs_case "ORK_PRE_PUSH_JOBS=0 is ignored (xargs -P 0 is unbounded)" 8 8 0   0

    # The banner must name the count BEFORE the run so a failed stage's log
    # still shows what parallelism it ran at.
    if grep -q 'jobs=\${MAX_JOBS}' "$hook"; then
        log_pass "stage banner prints jobs=\${MAX_JOBS}"
    else
        log_fail "stage banner does not print the chosen job count"
    fi
    if grep -q 'xargs -P "\$MAX_JOBS"' "$hook"; then
        log_pass "xargs -P still reads \$MAX_JOBS"
    else
        log_fail "xargs -P no longer reads \$MAX_JOBS"
    fi
}

# Test 12: one sustained-load job count reaches unit, security, and vitest (#4238).
#
# The three runners are stubs on PATH. No real suite runs. The 5-minute load
# is an argument, the same way Test 10 feeds resolve_pre_push_jobs, so the
# machine's own load cannot leak in.
test_shared_load_backoff_fixture() {
    log_section "Test 12: every stage receives one 5-minute load back-off (#4238)"

    local hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    local tmp bin stub_log fns out count notice
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-pre-push-backoff.XXXXXX")
    bin="$tmp/bin"
    stub_log="$tmp/stub.log"
    mkdir -p "$bin"

    fns=$(sed -n '/^load5_from_uptime_tail()/,/^}/p' "$hook")
    fns+=$'\n'"$(sed -n '/^resolve_pre_push_jobs()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^refresh_pre_push_load_notice()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^print_pre_push_load_notice()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^plan_pre_push_jobs()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^run_captured()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^run_unit_tests_parallel()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^run_security_stage()/,/^}/p' "$hook")"
    fns+=$'\n'"$(sed -n '/^run_hooks_vitest_stage()/,/^}/p' "$hook")"
    printf '%s\n' "$fns" > "$tmp/fns.sh"
    # This extracted copy calls the logging stub by path. The hook does not
    # grow a PATH switch to make that possible.
    sed "s#\\./tests/security/run-security-tests.sh#${bin}/run-security-tests.sh#" "$tmp/fns.sh" > "$tmp/fns.stub.sh"
    mv "$tmp/fns.stub.sh" "$tmp/fns.sh"

    if [[ -z "$fns" || "$fns" != *'run_hooks_vitest_stage()'* ]]; then
        log_fail "could not extract the three stage runners from the hook"
        rm -rf "$tmp"
        return
    fi

    printf '%s\n' \
        '#!/bin/bash' \
        'printf "XARGS %s\n" "$*" >> "$STUB_LOG"' \
        'cat >/dev/null' \
        'exit 0' > "$bin/xargs"
    printf '%s\n' \
        '#!/bin/bash' \
        'printf "SECURITY jobs=%s args=%s\n" "${ORK_PRE_PUSH_STAGE_JOBS:-unset}" "$*" >> "$STUB_LOG"' \
        'exit 0' > "$bin/run-security-tests.sh"
    printf '%s\n' \
        '#!/bin/bash' \
        'printf "NPX %s\n" "$*" >> "$STUB_LOG"' \
        'exit 0' > "$bin/npx"
    chmod +x "$bin/xargs" "$bin/run-security-tests.sh" "$bin/npx"

    local second
    second=$(/bin/bash -c 'source "$1"; load5_from_uptime_tail "$2"' _ "$tmp/fns.sh" "1.25 80.5 9.0")
    if [[ "$second" == "80.5" ]]; then
        log_pass "uptime tail uses the 5-minute field (80.5), not the 1-minute dip (1.25)"
    else
        log_fail "uptime tail returned [$second], want 80.5"
    fi
    second=$(/bin/bash -c 'source "$1"; load5_from_uptime_tail "$2"' _ "$tmp/fns.sh" "0.10, 80.50, 9.00")
    if [[ "$second" == "80.50" ]]; then
        log_pass "comma-separated uptime tail still yields the middle field"
    else
        log_fail "comma uptime tail returned [$second], want 80.50"
    fi

    # run_case <ncpu> <load5>
    run_case() {
        : > "$stub_log"
        out=$(cd "$PROJECT_ROOT" && env -u ORK_PRE_PUSH_JOBS \
            PATH="$bin:$PATH" \
            STUB_LOG="$stub_log" \
            /bin/bash -c '
                set -u
                source "$1"
                CI_UNIT_TESTS=(fixture-unit.sh)
                plan_pre_push_jobs "$2" "$3"
                run_unit_tests_parallel
                run_security_stage
                run_hooks_vitest_stage
            ' _ "$tmp/fns.sh" "$1" "$2")
    }

    notice="pre-push: sustained load 80, jobs=1"
    run_case 16 80
    count=$(printf '%s\n' "$out" | awk -v needle="$notice" \
        'index($0, needle) { count++ } END { print count + 0 }')
    if [[ "$count" -eq 3 ]]; then
        log_pass "load 80 on 16 cores: the shared notice is printed by all 3 stages"
    else
        log_fail "load 80 notice count=$count (want 3). output: $out"
    fi
    if grep -F -q -- '-P 1 ' "$stub_log" \
        && grep -F -q 'SECURITY jobs=1 args=' "$stub_log" \
        && grep -F -q -- '--maxWorkers=1' "$stub_log"; then
        log_pass "load 80 on 16 cores: unit, security, and vitest all receive jobs=1"
    else
        log_fail "load 80 stub log did not show jobs=1: $(cat "$stub_log")"
    fi

    run_case 16 0
    count=$(printf '%s\n' "$out" | awk \
        '/pre-push: sustained load/ { count++ } END { print count + 0 }')
    if [[ "$count" -eq 0 ]]; then
        log_pass "idle 16-core box prints no load notice"
    else
        log_fail "idle box printed a load notice: $out"
    fi
    if grep -F -q -- '-P 8 ' "$stub_log" \
        && grep -F -q 'SECURITY jobs=8 args=' "$stub_log" \
        && grep -F -q -- '--maxWorkers=8' "$stub_log"; then
        log_pass "idle 16-core box keeps the old cap of 8 on every stage"
    else
        log_fail "idle stub log was not the cap of 8: $(cat "$stub_log")"
    fi

    rm -rf "$tmp"
}

# A captured stage that exits 7 must make the hook exit 7.
# Reading $? after the if reports 0, so the gate used to pass.
# The typecheck stage runs src/hooks/node_modules/.bin/tsc directly (#4220),
# so stub that binary (npx is no longer on this path).
test_captured_stage_exit_status() {
    log_section "Test: captured stage exit status is the hook exit status"

    local tmp hook rc out kept tsc_bin tsc_backup=""
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-pre-push-rc.XXXXXX")
    hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    tsc_bin="${PROJECT_ROOT}/src/hooks/node_modules/.bin/tsc"

    if [[ ! -x "$tsc_bin" ]]; then
        log_fail "local tsc missing at $tsc_bin (typecheck stage would SKIP, not exercise capture)"
        rm -rf "$tmp"
        return
    fi

    tsc_backup="$tmp/tsc.real"
    mv "$tsc_bin" "$tsc_backup"
    printf '%s\n' '#!/bin/bash' 'exit 7' > "$tsc_bin"
    chmod +x "$tsc_bin"
    restore_tsc() {
        if [[ -n "$tsc_backup" && -f "$tsc_backup" ]]; then
            mv -f "$tsc_backup" "$tsc_bin"
        fi
    }
    trap restore_tsc EXIT

    rc=0
    out=$(/bin/bash "$hook" origin "https://example.invalid/repo.git" \
        <<<'refs/heads/chore/exit-status 0000000000000000000000000000000000000000 refs/heads/chore/exit-status 0000000000000000000000000000000000000000') || rc=$?

    restore_tsc
    trap - EXIT

    if [[ "$rc" -eq 7 ]]; then
        log_pass "stubbed stage exit 7 is the hook exit status"
    else
        log_fail "hook exited $rc, want 7. output: $out"
    fi
    kept=$(printf '%s\n' "$out" | sed -n 's/.*Full log kept at: //p')
    if [[ -n "$kept" ]]; then
        rm -f "$kept"
    fi
    rm -rf "$tmp"
}

# A PATH-resolved run-security-tests.sh must not satisfy the security stage,
# even when ORK_PRE_PUSH_PATH_STUBS=1. The checkout script is the only runner.
test_security_stage_rejects_path_stub() {
    log_section "Test: PATH cannot satisfy the security stage"

    local hook tmp bin marker fns out
    hook="${PROJECT_ROOT}/bin/git-hooks/pre-push"
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/ork-pre-push-path.XXXXXX")
    bin="$tmp/bin"
    marker="$tmp/marker"
    mkdir -p "$bin"
    printf '%s\n' '#!/bin/bash' "printf '%s\n' PATH_STUB > '$marker'" 'exit 0' > "$bin/run-security-tests.sh"
    chmod +x "$bin/run-security-tests.sh"

    fns=$(sed -n '/^print_pre_push_load_notice()/,/^}/p' "$hook")
    fns+=$'\n'"$(sed -n '/^run_security_stage()/,/^}/p' "$hook")"
    printf '%s\n' "$fns" > "$tmp/fns.sh"

    out=$(cd "$tmp" && PATH="$bin:$PATH" ORK_PRE_PUSH_PATH_STUBS=1 /bin/bash -c '
        set -u
        PRE_PUSH_LOAD_NOTICE=""
        MAX_JOBS=4
        source "$1"
        run_security_stage
    ' _ "$tmp/fns.sh")

    if [[ -f "$marker" ]]; then
        log_fail "PATH stub ran and could satisfy the security stage. output: $out"
    else
        log_pass "PATH stub was not executed"
    fi
    if printf '%s\n' "$out" | grep -F -q 'SKIP (not found)'; then
        log_pass "missing checkout script is a skip, not a PATH success"
    else
        log_fail "expected SKIP (not found), got: $out"
    fi
    rm -rf "$tmp"
}

main() {
    echo "╔═══════════════════════════════════════════════════════════════╗"
    echo "║            Pre-push Hook Unit Tests                          ║"
    echo "╚═══════════════════════════════════════════════════════════════╝"

    test_run_with_timeout_exit_codes
    test_changelog_variable_capture
    test_run_with_timeout_spaces
    test_skip_regex_parity
    test_bash32_compatibility
    test_resolve_push_branch
    test_rejects_repo_config_drift
    test_probe_fixture_git_environment_scrub
    test_vitest_git_environment_scrub
    test_resolve_pre_push_jobs
    test_shared_load_backoff_fixture
    test_captured_stage_exit_status
    test_security_stage_rejects_path_stub
    test_stages_do_not_inherit_worktree_git_dir
    test_scrub_keeps_locators_without_rediscovery

    # Summary
    echo ""
    echo "═══════════════════════════════════════════════════════════════"
    echo "                        TEST SUMMARY"
    echo "═══════════════════════════════════════════════════════════════"
    echo -e "  Passed:  ${GREEN}${TESTS_PASSED}${NC}"
    echo -e "  Failed:  ${RED}${TESTS_FAILED}${NC}"
    echo ""

    if [[ $TESTS_FAILED -gt 0 ]]; then
        echo -e "${RED}FAIL${NC}: Some tests failed"
        exit 1
    else
        echo -e "${GREEN}PASS${NC}: All tests passed"
        exit 0
    fi
}

main "$@"
